from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from gongbi_training.runtime import configure,LAB
configure()
from PIL import Image,ImageDraw,ImageFont
ROOT=LAB/'cunfa_context_reference_20261111'
def read(n):return json.loads((ROOT/n).read_text('utf8'))
def save(n,d):(ROOT/n).write_text(json.dumps(d,ensure_ascii=False,indent=2),encoding='utf8')
def main():
 s=read('summary.json');audit=read('audit_summary.json');inputs=read('input_manifest.json');ref=read('object_reference.json');checks=read('verification.json');methods={'local_only':'预训练特征：仅局部','context_only':'预训练特征：仅周围画面','local_plus_context':'预训练特征：局部＋周围画面','gabor':'Gabor＋PCA＋SVM'}
 results={k:read(k+'_evaluation.json') for k in methods if k!='gabor'};results['gabor']=read('gabor_same63_author_cv.json');maps={k:{r['id']:r for r in v['predictions']} for k,v in results.items()};views={r['id']:r for r in inputs['views']}
 rows=[]
 for r in inputs['rows']:
  rows.append(dict(id=r['id'],label=r['label'],artist=r['artist_group'],publisher=r['publisher_group'],source_url=r['source_url'],label_scope=r['label_scope'],source_box=r['source_box'],context_box=views[r['id']]['context_box'],local='inputs/'+r['id']+'_local.png',context='inputs/'+r['id']+'_context.png',predictions={k:maps[k][r['id']]['predicted'] for k in methods}))
 payload=dict(summary=s,audit=audit,methods=methods,results=results,records=rows,reference=ref,verification=checks,protocol=read('protocol.json'),publisher_folds=read('local_plus_context_publisher_stress.json')['folds']);save('report_data.json',payload)
 font=lambda n:ImageFont.truetype('C:/Windows/Fonts/msyh.ttc',n)
 im=Image.new('RGB',(1440,920),'#f4f1e8');d=ImageDraw.Draw(im);d.text((30,22),'皴法分类探索：加入周围画面后，一致率有改善',font=font(33),fill='#233e32');d.text((30,80),'同一63例，按13位作者留出；仍是已查看资料，非新封存测试，专家局部标签为0。',font=font(23),fill='#425a4c')
 pairs=[('Gabor基线（本轮同63例重跑）',audit['same63_gabor']),('预训练视觉特征：仅局部',s['metrics']['local_only']['label_agreement']),('预训练视觉特征：局部＋周围画面',s['metrics']['local_plus_context']['label_agreement'])]
 for i,(label,v) in enumerate(pairs):
  y=175+i*115;d.text((30,y),label,font=font(23),fill='#233e32');d.rectangle((590,y+2,590+v*630,y+36),fill='#507b68');d.text((1210,y-1),f'{v:.1%}',font=font(26),fill='#233e32')
 d.text((30,535),'更严格的来源检查：按发布机构留出，局部＋上下文为76.2%。',font=font(25),fill='#233e32');d.text((30,582),'AAM 66.7%（15例）　DPM 83.3%（42例）　NPM 50.0%（6例）',font=font(23),fill='#775236')
 d.text((30,657),'可以支持：继续验证上下文分类路线。',font=font(27),fill='#30684c');d.text((30,710),'还不能支持：懂得真实笔组、还原笔顺、生成皴法或让机械臂复现。',font=font(25),fill='#9b452e')
 d.text((30,768),'网络编码器保持冻结，只训练了分类头；上下文是2.5倍邻域，并非自动识别整块山石。',font=font(21),fill='#425a4c');d.text((30,811),'已查看样本需转为开发数据，下一次需新增独立作者/作品并复核局部标签。',font=font(21),fill='#425a4c');d.text((30,855),'本轮没有替换绘画版本，也没有连接机械臂。',font=font(21),fill='#425a4c');im.save(ROOT/'comparison.png')
 page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>皴法上下文探索 · 分类与分层参考</title><style>body{margin:0;background:#f4f1e8;color:#233e32;font:16px/1.7 system-ui}main{max-width:1260px;margin:auto;padding:26px}h1{font-size:29px}h2{font-size:23px;margin-top:32px}.note{background:#e3eadd;padding:18px;border-left:5px solid #507b68}.caution{background:#f1ded0;padding:16px}.overview{width:100%;height:auto}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:16px}.card{background:#fffdf7;border:1px solid #d7d8c8;border-radius:8px;padding:15px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:8px}.pair img{width:100%;height:170px;object-fit:contain;background:white}small{display:block;color:#596b5b;overflow-wrap:anywhere}a{color:#205c40}select{max-width:100%;padding:10px;margin:6px;background:#fffdf7;border:1px solid #adb3a1;border-radius:5px}.good{color:#24664b}.bad{color:#a0412b}details{margin-top:10px}summary{cursor:pointer}table{border-collapse:collapse;width:100%}td,th{border-bottom:1px solid #ccd0bd;text-align:left;padding:9px}.tablewrap{overflow-x:auto}pre{white-space:pre-wrap;overflow-wrap:anywhere}.reference img{width:100%;height:auto}</style><main><h1>皴法上下文探索：分类输出与山石分层参考</h1><div class="note"><b>本轮进展：在已有资料的分组测试中，局部＋周围画面优于仅局部。</b><br>数据仍为63个候选区域（披麻32、斧劈31），13位署名/归属作者。分类主试验按作者留出，一致率85.7%；Gabor在同63例上重跑为61.9%，仅局部预训练视觉特征为60.3%。这是与来源标签的一致情况，不是专家准确率。数据此前均已看过，不能称为新封存测试。</div><p>模型用本机已有的ImageNet MobileNetV3-small特征，编码器未训练，只训练线性SVM分类头。输入先转灰度均衡，保持比例缩放；第二路是局部周围2.5倍窗口。它没有自动找到整块山石，也未接受真实笔组、逐笔墨迹或起落笔监督。</p><img class="overview" src="comparison.png" alt="同63例作者留出比较"><h2>全部方法与来源检查</h2><div class="tablewrap"><table><thead><tr><th>方法</th><th>作者留出一致率</th><th>macro-F1</th><th>披麻召回</th><th>斧劈召回</th></tr></thead><tbody id="metrics"></tbody></table></div><p>相比只看局部，双路模型有19例改对、3例改错。超参数只由各轮训练作者的内层分组选择，未将本轮留出作者用于拟合分类头。所有作者的裁剪、同作品、同原图保持在同组，原有5个其他皴法探针未进训练。</p><div class="caution"><b>事后来源压力检查：</b>按3个发布机构留出，双路模型整体76.2%；AAM 10/15，DPM 35/42，NPM 3/6。三个来源平均66.7%，不能只看被42例DPM主导的整体值。这个检查没有参与选择主方法，仍不是新增独立专家测试，也没有排除所有纸纹、扫描方式或构图差异。</div><h2>模型直接输出：逐例分类，没有生成笔触</h2><select id="method"></select><select id="artist"><option value="">全部作者</option></select><select id="status"><option value="">全部结果</option><option value="wrong">与来源标签不符</option><option value="correct">与来源标签一致</option></select><span id="count"></span><div id="grid" class="grid"></div><h2>一块山石的分层参考：原作与助手标记</h2><p>以下选自王履《华山图册》的可见右侧山石。馆藏说明为小斧劈皴，具体局部的边界与笔组仍需核查。图中的轮廓引导、笔组候选区域均是助手整理，不是模型输出；没有把未知的单笔归属、笔顺、笔宽变化或压力强行填上，也未用它们训练分类器。</p><div class="reference"><img src="object_reference.png" alt="助手可见结构参考，非模型输出"></div><details><summary>查看参考具体状态</summary><pre id="reference"></pre></details><h2>接下来的验证范围</h2><p>应冻结这条上下文路线，再补从未参与开发的独立作者和作品，按区域复核皴法与混合状态。完整山石参考还需核查实际皴笔成员和可见墨带，明确待定区，才能训练笔组组织与生成。本轮模型尚不输出长笔触、实际笔序或机械臂参数，当前绘画版本维持原状。</p><p>资料与方法：<a href="https://www.dpm.org.cn/collection/paint/228140.html" target="_blank" rel="noopener">王履华山图册馆藏说明</a> · <a href="https://docs.pytorch.org/vision/stable/models/generated/torchvision.models.mobilenet_v3_small.html" target="_blank" rel="noopener">MobileNetV3官方模型文档</a>。每例还保留其原始来源链接，来源标签不是专家局部真值。</p><details><summary>方案与完整性检查</summary><pre id="checks"></pre></details><p><a href="report_data.json">对照数据</a> · <a href="object_reference.json">分层参考记录</a></p></main><script>
const el=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let DATA;const pct=v=>(v*100).toFixed(1)+'%';
fetch('report_data.json').then(r=>r.json()).then(d=>{DATA=d;el('method').innerHTML=Object.entries(d.methods).map(([k,v])=>`<option value="${k}">${v}</option>`).join('');el('method').value='local_plus_context';el('artist').innerHTML+=[...new Set(d.records.map(r=>r.artist))].map(a=>`<option>${a}</option>`).join('');el('metrics').innerHTML=Object.entries(d.results).map(([k,e])=>{const m=e.metrics||e;return `<tr><td>${esc(d.methods[k])}</td><td>${pct(m.label_agreement)}</td><td>${m.macro_f1.toFixed(3)}</td><td>${pct(m.class_recall[0])}</td><td>${pct(m.class_recall[1])}</td></tr>`}).join('');el('reference').textContent=JSON.stringify(d.reference,null,2);el('checks').textContent=JSON.stringify({verification:d.verification,protocol:d.protocol},null,2);for(const id of ['method','artist','status'])el(id).onchange=draw;draw();window.reportReady=true;});
function draw(){const k=el('method').value,a=el('artist').value,s=el('status').value;const rows=DATA.records.filter(r=>(!a||r.artist===a)&&(!s||s==='wrong'&&r.label!==r.predictions[k]||s==='correct'&&r.label===r.predictions[k]));el('count').textContent=`显示 ${rows.length}/63`;el('grid').innerHTML=rows.map(r=>`<article class="card"><div class="pair"><div><small>局部输入</small><img src="${r.local}" alt="${r.id}局部"></div><div><small>2.5倍周围画面输入</small><img src="${r.context}" alt="${r.id}上下文"></div></div><small>${r.id} · ${r.artist} · ${r.publisher}</small><b>来源候选：${r.label}</b><br><b class="${r.label===r.predictions[k]?'good':'bad'}">模型分类：${r.predictions[k]}</b><details><summary>所有方法与来源</summary>${Object.entries(r.predictions).map(([key,v])=>`<small class="${v===r.label?'good':'bad'}">${esc(DATA.methods[key])}：${v}</small>`).join('')}<small>${esc(r.label_scope)}<br>局部框：${r.source_box.join(', ')}<br>邻域框：${r.context_box.join(', ')}</small><a href="${r.source_url}" target="_blank" rel="noopener">核对原始来源</a></details></article>`).join('');}
</script></html>'''
 (ROOT/'index.html').write_text(page,encoding='utf8')
 note=f'''# 皴法上下文分类探索与可见结构参考（2026-11-11）

本轮采用本机E盘已有ImageNet MobileNetV3-small，冻结编码器，仅训练线性SVM头。局部及周围2.5倍邻域转灰度均衡，保持比例缩放至224，使用ImageNet通道归一化，和官方默认中央裁剪有所不同。邻域不是自动整块山石分割，也没有训练真实笔组关系。

旧63例，13位作者，32披麻31斧劈；全部为已查看资料，非新独立测试。按作者外层LOGO，内层作者GroupKFold选C[.1,1,10]。同作者、作品、源图不跨折。对照：Gabor同63例重新运行61.9%/macroF1=.6143；预训练仅局部60.3%/.6028；仅上下文79.4%/.7928；双路85.7%/.8571。双路相对局部19例改对、3例改错。模型分类头导出后的训练集预测不用于这些指标。

事后来源检查整体双路76.2%，AAM10/15、DPM35/42、NPM3/6，机构平均66.7%。有来源差异风险，不声称排除了捷径或具有广泛泛化；不能将这一探索结果视为专家真实准确率。原5个其他类型探针未进训练，未知/混合没有训练好。

整理王履山石可见结构参考：2段外轮廓引导、2段山面边界引导、2个笔组候选区、1个待定区。全部助手候选，不是完整已核实笔画；P01附近墨迹支持仅59.7%标为待定边界，其他近墨迹支持不能证明唯一笔触归属。逐笔身份、方向、笔顺、压力均空；不用于分类或笔触监督，未知不当负例。保留原作墨带形态，不把细线引导渲染成复现成果。原画为边缘可见山石范围，遮挡边界不补闭合。

已通过源/裁剪哈希、作者/作品/源图隔离、模型保存重载和页面检查。没有安装依赖、下载权重、接入机械臂或替换绘画版本。下一步需冻结方案后加入新作品与局部复核，再谈笔组生成，不把本轮辅助标记自动作为真值。输出：{ROOT}
'''
 (Path(__file__).resolve().parents[1]/'research'/'cunfa_context_reference_status_20261111.md').write_text(note,encoding='utf8');print('REPORT_READY',flush=True)
